css:
[data-theme="black"] .card,
[data-theme="black"] .web-link,
[data-theme="black"] .icon-btn,
[data-theme="black"] .small-icon-btn,
[data-theme="black"] .action-btn,
[data-theme="black"] .top-menu,
[data-theme="black"] .top-menu-item,
[data-theme="black"] .edit-input,
[data-theme="black"] .edit-select,
[data-theme="black"] .search-box,
[data-theme="black"] .modal,
[data-theme="black"] .editor-row {
  border-color: transparent !important;
  box-shadow: none !important;
}

[data-theme="black"] .card,
[data-theme="black"] .web-link,
[data-theme="black"] .icon-btn,
[data-theme="black"] .small-icon-btn,
[data-theme="black"] .action-btn {
  background: #2f2f2f;
}

[data-theme="black"] .card:hover,
[data-theme="black"] .web-link:hover,
[data-theme="black"] .icon-btn:hover,
[data-theme="black"] .small-icon-btn:hover,
[data-theme="black"] .action-btn:hover {
  background: #3a3a3a;
}

[data-theme="black"] .top-menu,
[data-theme="black"] .modal {
  background: #2b2b2b;
}

[data-theme="black"] .top-menu-item:hover {
  background: #383838;
}

[data-theme="black"] .top-menu {
  background: #242424 !important;
  color: #f2f2f2 !important;
  border: 0 !important;
  box-shadow: 0 8px 24px rgba(0,0,0,.55) !important;
}
[data-theme="black"] .top-menu-label {
  color: #a9a9a9 !important;
}
[data-theme="black"] .top-menu-item {
  background: transparent !important;
  color: #ececec !important;
  border: 0 !important;
}
[data-theme="black"] .top-menu-item i,
[data-theme="black"] .top-menu-item span {
  color: inherit !important;
}
[data-theme="black"] .top-menu-item:hover {
  background: #343434 !important;
  color: #ffffff !important;
}
[data-theme="black"] .top-menu-item.active {
  background: #303030 !important;
  color: #ffffff !important;
}
[data-theme="black"] .top-menu-item.active .menu-check {
  color: #ffffff !important;
  opacity: 1 !important;
}

[data-theme="black"] .top-menu-separator {
  border-color: #3a3a3a !important;
  background: #3a3a3a !important;
}

[data-theme="black"] button.delete-btn {
  background: transparent !important;
  color: #ff6b6b !important;
  border: 1px solid rgba(255,107,107,.38) !important;
}
[data-theme="black"] button.delete-btn:hover {
  background: rgba(255,107,107,.10) !important;
  color: #ff8a8a !important;
  border-color: rgba(255,107,107,.65) !important;
}

[data-theme="black"] body {
  background: #000 !important;
}
[data-theme="black"] .web-link,
[data-theme="black"] .web-link:hover {
  background: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
}
